import NodeCache from 'node-cache';

const cache = new NodeCache({
  stdTTL: 300,          // 5 minutes default TTL
  checkperiod: 120,     // check for expired keys every 2 min
  useClones: false,     // return references directly (faster)
});

// Write
cache.set('user:42', { name: 'Alice', role: 'admin' }, 600);

// Read (returns undefined on miss)
const user = cache.get('user:42');

// Delete
cache.del('user:42');

// TTL-aware read
const ttl = cache.getTtl('user:42');
